"""Español — profetas, parte C (prophets_151 … prophets_250)."""

T = {
"prophets_151": ("¿De qué se les prohibió acercarse a Adán y a su esposa en el Jardín?", ["De un árbol", "De un río", "De una puerta", "De una montaña"], "Allah les permitió comer con holgura, salvo acercarse a un solo árbol."),
"prophets_152": ("Según el Corán, ¿qué recibió Adán de su Señor tras su falta?", ["Unas palabras (de arrepentimiento), y Allah aceptó su arrepentimiento", "Riqueza", "Un reino", "Un libro"], "«Adán recibió unas palabras de su Señor, y Él aceptó su arrepentimiento»."),
"prophets_153": ("¿Con quién compara el Corán a 'Isa en cuanto a su creación?", ["Con Adán, creado de tierra", "Con Nuh (Noé)", "Con Ibrahim (Abraham)", "Con Yahya (Juan)"], "«El caso de 'Isa ante Allah es como el de Adán: lo creó de tierra y luego le dijo: “Sé”, y fue»."),
"prophets_154": ("¿De qué profeta dice el Corán que fue veraz y que Allah lo elevó a un lugar eminente?", ["Idris (Enoc)", "Ilyas (Elías)", "Dhul-Kifl", "Al-Yasa' (Eliseo)"], "«Y recuerda en el Libro a Idris: fue veraz, un profeta; y lo elevamos a un lugar eminente»."),
"prophets_155": ("¿Qué dijo Nuh cuando los suyos subieron al arca?", ["«En el nombre de Allah sea su singladura y su fondeadero»", "«No temáis al mar»", "«Tomad vuestras provisiones»", "«Esperad la noche»"], "«Subid a ella: en el nombre de Allah sea su rumbo y su fondeadero»."),
"prophets_156": ("En la sura Nuh, ¿qué pidió el profeta Nuh a su Señor respecto a los incrédulos?", ["Que no dejara sobre la tierra a ninguno de ellos", "Que los enriqueciera", "Que les diera un año más", "Que los desterrara"], "«Señor mío, no dejes sobre la tierra a ningún incrédulo»."),
"prophets_157": ("¿Cuántos de cada especie debía embarcar Nuh en el arca?", ["Una pareja", "Tres", "Diez", "Uno solo"], "Allah le ordenó cargar en ella una pareja de cada especie, junto con su familia."),
"prophets_158": ("Hud recordó a 'Ad que Allah los había hecho sucesores ¿después de qué pueblo?", ["Del pueblo de Nuh (Noé)", "Del pueblo de Lut (Lot)", "Del pueblo de Musa (Moisés)", "Del pueblo de Saba"], "«Recordad cuando os hizo sucesores después del pueblo de Nuh y os dio mayor corpulencia»."),
"prophets_159": ("¿Con qué fue destruido el pueblo de 'Ad, según la sura Al-Haqqa?", ["Con un viento gélido y bramador", "Con un diluvio", "Con un terremoto", "Con una plaga de langostas"], "«En cuanto a 'Ad, fueron destruidos por un viento glacial y violento»."),
"prophets_160": ("¿Qué reprochó Hud a su pueblo, que edificaba en cada altura?", ["Edificar por vanidad y esperar vivir eternamente", "Cultivar la tierra", "Comerciar lejos", "Viajar de noche"], "«¿Edificáis en cada altura un monumento por diversión, y tomáis palacios como si fuerais a vivir eternamente?»"),
"prophets_161": ("¿Qué hacía Zamud con las montañas, según el Corán?", ["Tallaba en ellas sus casas", "Escondía oro en ellas", "Pastoreaba rebaños en ellas", "Las evitaba"], "«Tomáis palacios en sus llanuras y talláis casas en las montañas»."),
"prophets_162": ("Según la sura Al-Qamar, ¿como qué fue enviada la camella a Zamud?", ["Como prueba para ellos", "Como recompensa", "Como regalo de su rey", "Como rebaño para vender"], "«Vamos a enviarles la camella como prueba: obsérvalos y ten paciencia»."),
"prophets_163": ("¿Qué se apoderó de Zamud tras matar a la camella?", ["El terremoto (ar-rayfa)", "El diluvio", "El viento gélido", "La hambruna"], "«El terremoto se apoderó de ellos, y amanecieron yaciendo en sus casas»."),
"prophets_164": ("¿Qué profeta fue enviado al pueblo que cometía la gran indecencia, diciéndoles «¿No vais a temer a Allah?»", ["Lut (Lot)", "Salih", "Hud", "Shu'ayb"], "«Cuando su hermano Lut les dijo: “¿No vais a temer a Allah?”»"),
"prophets_165": ("¿Qué se le ordenó a Lut la noche del castigo?", ["Partir de noche con su familia y no volver la vista", "Reunir a su pueblo", "Esperar el alba", "Esconderse en la montaña"], "«Parte, pues, con tu familia en parte de la noche, y que ninguno de vosotros vuelva la vista»."),
"prophets_166": ("¿Qué profeta fue enviado a la gente de Madián, que defraudaba en la medida y el peso?", ["Shu'ayb", "Lut (Lot)", "Hud", "Ilyas (Elías)"], "Shu'ayb les ordenó dar la medida completa y el peso justo, y no sembrar corrupción en la tierra."),
"prophets_167": ("¿Qué dijo Shu'ayb a su pueblo sobre lo que de verdad quería?", ["«Solo quiero la reforma, en la medida de mis fuerzas»", "«Solo quiero riqueza»", "«Quiero gobernar»", "«Quiero marcharme»"], "«Solo quiero la reforma, en la medida de mis fuerzas. Y mi éxito solo depende de Allah»."),
"prophets_168": ("Después de que Allah probara a Ibrahim con mandatos que cumplió, ¿qué le dijo?", ["«Voy a hacer de ti un guía (imam) para los hombres»", "«Voy a darte un reino»", "«Voy a enriquecerte»", "«Voy a hacerte rey de Babilonia»"], "«Voy a hacer de ti un guía para los hombres». Ibrahim preguntó: «¿Y de mi descendencia?»"),
"prophets_169": ("¿Cómo dejó Ibrahim sin respuesta al rey que pretendía dar la vida y la muerte?", ["«Allah trae el sol por oriente: tráelo tú por occidente»", "«Haz caer la lluvia»", "«Mueve esa montaña»", "«Cuenta las estrellas»"], "«Allah trae el sol por oriente; tráelo tú por occidente». Y el incrédulo quedó confundido."),
"prophets_170": ("¿Qué se le ordenó a Ibrahim proclamar a la gente sobre la Casa Sagrada?", ["La peregrinación: vendrán a pie y en toda montura", "El comercio", "La guerra", "El silencio"], "«Y proclama entre los hombres la peregrinación: vendrán a ti a pie y en toda montura esbelta»."),
"prophets_171": ("¿Qué ofreció Ibrahim a sus huéspedes honrados, que no lo tocaron?", ["Un ternero cebado asado", "Pan y agua", "Dátiles", "Leche"], "Fue a los suyos y trajo un ternero cebado; al ver que no alargaban las manos hacia él, sintió temor."),
"prophets_172": ("¿De quién dice el Corán que es «un hermoso ejemplo» (uswa hasana) para los creyentes, junto con los que estaban con él?", ["Ibrahim (Abraham)", "Nuh (Noé)", "Musa (Moisés)", "Dawud (David)"], "«Tenéis un hermoso ejemplo en Ibrahim y en quienes estaban con él»."),
"prophets_173": ("En la sura Ibrahim, ¿qué pidió Ibrahim para la ciudad de La Meca?", ["Que fuera segura, y que él y sus hijos se libraran de adorar ídolos", "Que se volviera un gran mercado", "Que tuviera palacios", "Que quedara desierta"], "«Señor mío, haz de esta ciudad un lugar seguro, y líbrame a mí y a mis hijos de adorar ídolos»."),
"prophets_174": ("¿Qué dijo Ibrahim al dejar a su pueblo?", ["«Me voy a mi Señor: Él me guiará»", "«Voy a buscar fortuna»", "«Volveré a combatirlos»", "«Me voy a Egipto»"], "«Me voy a mi Señor: Él me guiará»."),
"prophets_175": ("¿De qué profeta dice el Corán que era «fiel a su promesa» y ordenaba a los suyos la oración y el zakat?", ["Isma'il (Ismael)", "Ishaq (Isaac)", "Ya'qub (Jacob)", "Yusuf (José)"], "«Era fiel a su promesa; fue un mensajero y un profeta. Ordenaba a su familia la oración y el zakat»."),
"prophets_176": ("¿Qué aconsejó Ya'qub a Yusuf tras su sueño?", ["Que no se lo contara a sus hermanos", "Que se lo contara a todos", "Que lo escribiera", "Que lo olvidara"], "«Hijito mío, no cuentes tu visión a tus hermanos, no sea que urdan algo contra ti»."),
"prophets_177": ("¿Qué indicio estableció la inocencia de Yusuf ante el señor de la casa?", ["Su túnica rasgada por detrás", "Un testigo escondido", "Una carta", "Un juramento"], "Si la túnica estaba rasgada por detrás, ella mintió y él es de los veraces."),
"prophets_178": ("¿Qué hicieron las mujeres de la ciudad al ver a Yusuf?", ["Se cortaron las manos, admiradas", "Huyeron", "Callaron", "Rieron"], "«Cuando lo vieron, quedaron maravilladas y se cortaron las manos, diciendo: “¡Este no es un ser humano; no es sino un ángel noble!”»"),
"prophets_179": ("¿Qué enseñó Yusuf a sus dos compañeros de prisión antes de interpretar sus sueños?", ["La unicidad de Allah, y que el juicio solo le pertenece a Él", "La medicina", "El cálculo de las cosechas", "La poesía"], "«¿Son mejores señores separados, o Allah, el Uno, el Dominador? … El juicio solo pertenece a Allah»."),
"prophets_180": ("¿Qué dijo el rey de Egipto a Yusuf tras hablar con él?", ["«Hoy tienes ante nosotros posición firme y confianza»", "«Vuelve a la prisión»", "«Sal de Egipto»", "«Te doy a mi hija»"], "«Cuando hubo hablado con él, dijo: “Hoy tienes ante nosotros posición firme y confianza”»."),
"prophets_181": ("¿Cómo retuvo Yusuf a su hermano consigo?", ["La copa del rey apareció en el equipaje de su hermano", "Lo compró", "Lo encarceló sin motivo", "Lo nombró ministro"], "«Así inspiramos esta estratagema a Yusuf»: la copa salió del saco de su hermano."),
"prophets_182": ("¿Qué dijo Yusuf a sus hermanos cuando reconocieron su falta?", ["«Hoy no hay reproche contra vosotros»", "«Seréis castigados»", "«Marchaos y no volváis»", "«Os he olvidado»"], "«Hoy no hay reproche contra vosotros. Que Allah os perdone: Él es el más misericordioso de los misericordiosos»."),
"prophets_183": ("¿Qué dijo Ya'qub a sus hijos sobre la desesperación?", ["«No desesperéis de la misericordia de Allah»", "«No volváis a partir»", "«No habléis con nadie»", "«No escribáis nada»"], "«No desesperéis del alivio de Allah: solo desesperan de él los incrédulos»."),
"prophets_184": ("¿Qué súplica hizo Yusuf al final de su historia?", ["Morir sometido (musulmán) y ser reunido con los justos", "Reinar sobre todo Egipto", "Volver a Canaán", "Vivir mucho tiempo"], "«Hazme morir sometido y reúneme con los justos»."),
"prophets_185": ("¿Cómo se dirigió Ayyub a su Señor en la prueba?", ["«Me ha tocado la desgracia, y Tú eres el más Misericordioso»", "«¿Por qué yo?»", "«Devuélveme mi riqueza»", "«Destruye a mis enemigos»"], "«Y recuerda a Nuestro siervo Ayyub, cuando invocó a su Señor: “El demonio me ha infligido fatiga y castigo”»."),
"prophets_186": ("¿Qué devolvió Allah a Ayyub tras la prueba, según la sura Sad?", ["Su familia, y otro tanto con ellos", "Un reino", "Un barco", "Un rebaño de camellos"], "«Le devolvimos su familia y otro tanto con ellos, como misericordia de Nuestra parte y recuerdo para los dotados de entendimiento»."),
"prophets_187": ("Según la sura As-Saffat, ¿qué salvó a Yunus de quedarse en el vientre del pez?", ["Que era de los que glorifican a Allah", "Su fuerza", "Un barco que pasaba", "Un viento favorable"], "«Si no hubiera sido de los que glorifican, habría permanecido en su vientre hasta el día en que sean resucitados»."),
"prophets_188": ("¿Qué pueblo, según el Corán, creyó antes de que le alcanzara el castigo, y le aprovechó?", ["El pueblo de Yunus (Jonás)", "El pueblo de Nuh", "El pueblo de Lut", "El pueblo de Hud"], "«¿Acaso hubo una ciudad que creyera y le aprovechara su fe, salvo el pueblo de Yunus?»"),
"prophets_189": ("¿Cómo nombra el Corán a Yunus cuando ordena al Profeta ﷺ no ser como él en su impaciencia?", ["«El compañero del pez» (sahib al-hut)", "«El hombre del bastón»", "«El hombre de la montaña»", "«El hombre del pozo»"], "«Y no seas como el compañero del pez, cuando invocó lleno de angustia»."),
"prophets_190": ("¿Qué profeta reprochó a su pueblo invocar a Ba'l y abandonar al mejor de los creadores?", ["Ilyas (Elías)", "Al-Yasa' (Eliseo)", "Yunus (Jonás)", "Shu'ayb"], "«Ilyas fue de los mensajeros… “¿Invocáis a Ba'l y abandonáis al mejor de los creadores?”»"),
"prophets_191": ("Junto a Isma'il e Idris, ¿a qué profeta menciona el Corán entre los pacientes que Allah admitió en Su misericordia?", ["Dhul-Kifl", "Ilyas (Elías)", "Yunus (Jonás)", "Al-Yasa' (Eliseo)"], "«E Isma'il, Idris y Dhul-Kifl: todos fueron de los pacientes. Y los admitimos en Nuestra misericordia»."),
"prophets_192": ("¿Qué hizo Allah por los Hijos de Israel ante el mar, perseguidos por Faraón?", ["Partió el mar y los salvó", "Hizo caer la noche", "Envió barcos", "Secó el mar para siempre"], "«Y cuando partimos el mar por vosotros: os salvamos y ahogamos a la gente de Faraón»."),
"prophets_193": ("¿Por qué pidió Musa a Allah que enviara a Harun con él?", ["Porque era más elocuente que él", "Porque era mayor", "Porque conocía Egipto", "Porque sabía escribir"], "«Mi hermano Harun es más elocuente que yo: envíalo, pues, conmigo como apoyo que me confirme»."),
"prophets_194": ("¿Cómo debían hablar Musa y Harun a Faraón?", ["Con palabras suaves", "Con amenazas", "Sin mirarlo", "Solo por escrito"], "«Y habladle con palabras suaves: quizá recapacite o tema»."),
"prophets_195": ("¿Quién, de la familia de Faraón, defendió a Musa ocultando su fe?", ["Un hombre creyente de la familia de Faraón", "El sumo sacerdote", "El jefe del ejército", "El visir Haman"], "«Y un hombre creyente de la familia de Faraón, que ocultaba su fe, dijo: “¿Vais a matar a un hombre porque dice: mi Señor es Allah?”»"),
"prophets_196": ("¿Qué dijo Harun a su pueblo durante la ausencia de Musa?", ["Que solo estaban siendo probados con el becerro, y debían seguirlo", "Que guardaran el becerro", "Que partieran a Egipto", "Que callaran"], "«Pueblo mío, solo estáis siendo probados con él. Vuestro Señor es el Compasivo: seguidme»."),
"prophets_197": ("¿Qué dijo la mujer de Faraón al encontrar al niño Musa?", ["«Será alegría para mis ojos y para los tuyos: no lo matéis»", "«Devolvedlo a su madre»", "«Llevadlo al río»", "«Vendedlo»"], "«Y dijo la mujer de Faraón: “Alegría para mis ojos y para los tuyos. No lo matéis: quizá nos sea útil”»."),
"prophets_198": ("¿Cómo pidió Musa seguir al siervo sabio (al-Jidr)?", ["«¿Puedo seguirte, a condición de que me enseñes?»", "«Ordéname y obedeceré»", "«Enséñame a cambio de un pago»", "«Ven conmigo»"], "«¿Puedo seguirte a condición de que me enseñes algo de la buena dirección que se te ha enseñado?»"),
"prophets_199": ("¿En qué estado volvió Musa a su pueblo tras ver el becerro?", ["Airado y afligido", "Alegre", "Silencioso", "Indiferente"], "«Y cuando Musa volvió a su pueblo, airado y afligido… arrojó las Tablas»."),
"prophets_200": ("¿Qué mensaje debía llevar Musa a Faraón según la sura An-Nazi'at?", ["«¿Quieres purificarte, y que te guíe hacia tu Señor?»", "«Devuélveme a mi pueblo»", "«Constrúyeme un palacio»", "«Sal de Egipto»"], "«Ve a Faraón: se ha excedido. Y dile: ¿quieres purificarte, y que te guíe hacia tu Señor para que Le temas?»"),
"prophets_201": ("¿Quién glorificaba a Allah junto con Dawud, al atardecer y al amanecer?", ["Las montañas y las aves", "Los ríos", "Las estrellas", "Los vientos"], "«Sometimos las montañas para que glorificaran con él al atardecer y al amanecer, y las aves reunidas»."),
"prophets_202": ("¿Qué dice el Corán que Allah dio a Dawud, junto con un reino firme?", ["La sabiduría y el discurso decisivo", "Ejércitos inmensos", "Oro y plata", "Un palacio de marfil"], "«Fortalecimos su reino y le dimos la sabiduría y el discernimiento en el hablar»."),
"prophets_203": ("¿Qué se le ordenó a Dawud al fabricar las cotas de malla?", ["Medir bien los eslabones", "Grabar en ellas su nombre", "Dorarlas", "Venderlas"], "«Haz cotas de malla completas, y mide bien los eslabones»."),
"prophets_204": ("¿Qué dijeron Dawud y Sulaiman cuando Allah les dio el conocimiento?", ["«Alabado sea Allah, que nos ha favorecido sobre muchos de Sus siervos creyentes»", "«Somos los mejores»", "«Nadie nos iguala»", "«Nos lo hemos merecido»"], "«Alabado sea Allah, que nos ha favorecido sobre muchos de Sus siervos creyentes»."),
"prophets_205": ("¿Qué hizo Sulaiman al oír a la hormiga advertir a los suyos?", ["Sonrió y pidió a Allah ser agradecido", "Se enfadó", "Desvió su ejército en silencio", "Ordenó silencio"], "«Sonrió al oír sus palabras y dijo: “Señor mío, permíteme agradecer Tu favor”»."),
"prophets_206": ("¿Qué noticia trajo la abubilla a Sulaiman?", ["Que una mujer reinaba en Saba y su pueblo se postraba ante el sol", "Que un ejército se acercaba", "Que había sequía", "Que había un tesoro escondido"], "«Vengo de Saba con una noticia cierta: he hallado a una mujer que reina sobre ellos… se postran ante el sol»."),
"prophets_207": ("¿Qué asombró a la reina de Saba al entrar en el palacio de Sulaiman?", ["El suelo de cristal, que tomó por agua", "Un león amansado", "Un jardín colgante", "Un trono de oro"], "«Se le dijo: “Entra en el palacio”. Al verlo, lo tomó por agua profunda y se descubrió las piernas. Él dijo: “Es un palacio pavimentado de cristal”»."),
"prophets_208": ("¿De qué estaban compuestos los ejércitos de Sulaiman, según el Corán?", ["De genios, hombres y aves", "Solo de jinetes", "De marineros", "Solo de arqueros"], "«Y fueron reunidos para Sulaiman sus ejércitos de genios, hombres y aves, en filas ordenadas»."),
"prophets_209": ("¿Cómo describió Zakariyya su estado al invocar a su Señor?", ["«Mis huesos se han debilitado y mi cabeza se ha encendido de canas»", "«Soy rico y saciado»", "«Estoy lejos de mi pueblo»", "«Estoy de viaje»"], "«Señor mío, mis huesos se han debilitado y mi cabeza se ha encendido de canas, y nunca he sido desdichado al invocarte»."),
"prophets_210": ("¿Qué señal se le dio a Zakariyya por el nacimiento de Yahya?", ["No hablar a la gente durante tres días, salvo por señas", "Una estrella", "Lluvia fuera de estación", "Un sueño repetido"], "«Tu señal es que no hablarás a la gente durante tres días, salvo por señas»."),
"prophets_211": ("¿Qué se le dijo a Yahya respecto al Libro?", ["«Toma el Libro con fuerza»", "«Esconde el Libro»", "«Copia el Libro»", "«Léelo una vez»"], "«¡Yahya, toma el Libro con determinación!» Y le dimos la sabiduría siendo aún niño."),
"prophets_212": ("¿Qué ordenaron los ángeles a Maryam tras anunciarle su elección?", ["Ser devota a su Señor, postrarse e inclinarse", "Emprender un viaje", "Callar para siempre", "Enseñar en el Templo"], "«Maryam, sé devota a tu Señor, póstrate e inclínate con los que se inclinan»."),
"prophets_213": ("¿Qué se le dijo a Maryam que sacudiera para comer, en el momento del parto?", ["El tronco de la palmera, para que cayeran dátiles frescos", "Un olivo", "Una higuera", "Una vid"], "«Sacude hacia ti el tronco de la palmera: hará caer sobre ti dátiles frescos y maduros»."),
"prophets_214": ("¿Qué dijo 'Isa en la cuna que Allah le había encomendado?", ["La oración y el zakat mientras viviera", "El comercio", "El silencio", "El viaje"], "«Me ha encomendado la oración y el zakat mientras viva»."),
"prophets_215": ("¿Cómo describe la sura Az-Zujruf a 'Isa hijo de Maryam?", ["Un siervo a quien Allah agració y puso como ejemplo para los Hijos de Israel", "Un rey de Israel", "Un ángel descendido", "Un escriba del Templo"], "«No fue sino un siervo a quien agraciamos y pusimos como ejemplo para los Hijos de Israel»."),
"prophets_216": ("¿Qué responderá 'Isa el Día de la Resurrección cuando Allah lo interrogue?", ["«¡Gloria a Ti! No me corresponde decir lo que no tengo derecho a decir»", "«No recuerdo»", "«Ellos lo escribieron»", "«Pregunta a los discípulos»"], "«¡Gloria a Ti! No me corresponde decir lo que no tengo derecho a decir»."),
"prophets_217": ("¿Cómo describe el Corán a 'Isa hijo de Maryam?", ["El mensajero de Allah, Su palabra dirigida a Maryam y un espíritu procedente de Él", "Un ángel enviado", "Un rey justo", "Un escriba sabio"], "«El Mesías, 'Isa hijo de Maryam, no es sino el mensajero de Allah, Su palabra que dirigió a Maryam y un espíritu procedente de Él»."),
"prophets_218": ("En la sura Ad-Duha, ¿de qué favores recuerda Allah a Su Profeta ﷺ?", ["Lo acogió huérfano, lo guio y lo enriqueció", "Le dio un reino", "Le dio un ejército", "Le dio un palacio"], "«¿No te halló huérfano y te dio amparo? ¿No te halló extraviado y te guio? ¿No te halló pobre y te enriqueció?»"),
"prophets_219": ("¿Qué promesa repite dos veces la sura Ash-Sharh?", ["«Con la dificultad viene la facilidad»", "«La victoria está cerca»", "«El Paraíso está prometido»", "«Los enemigos perecerán»"], "«Con la dificultad viene la facilidad. Con la dificultad viene la facilidad»."),
"prophets_220": ("¿Qué se le concedió al Profeta ﷺ en la sura Al-Kawzar, y qué se le ordenó a cambio?", ["Al-Kawzar; orar a su Señor y sacrificar", "Un ejército; combatir", "Un reino; gobernar", "Un tesoro; repartirlo"], "«Te hemos concedido al-Kawzar. Ora, pues, a tu Señor y sacrifica»."),
"prophets_221": ("¿Cómo describe la sura At-Tawba al Mensajero ﷺ para con los creyentes?", ["Solícito con ellos, benévolo y misericordioso", "Duro y distante", "Rico y poderoso", "Callado y retirado"], "«Os ha llegado un Mensajero de entre vosotros… solícito con vosotros, benévolo y misericordioso con los creyentes»."),
"prophets_222": ("Según el Corán, ¿qué habría alejado a la gente del Profeta ﷺ, de haber sido así?", ["Haber sido áspero y duro de corazón", "Haber sido rico", "Haber sido joven", "Haber sido silencioso"], "«Por una misericordia de Allah fuiste suave con ellos. Si hubieras sido áspero y duro de corazón, se habrían dispersado de tu alrededor»."),
"prophets_223": ("¿Qué dice el Corán del Mensajero de Allah ﷺ para quienes esperan en Allah y el Último Día?", ["Es para ellos un hermoso ejemplo", "Es un rey", "Es un juez", "Es un guía de caravanas"], "«Tenéis en el Mensajero de Allah un hermoso ejemplo para quien espera en Allah y en el Último Día»."),
"prophets_224": ("¿A quién fue enviado el Profeta Muhammad ﷺ, según la sura Saba?", ["A toda la humanidad", "Solo a Quraish", "Solo a los árabes", "A la gente de Medina"], "«No te hemos enviado sino como anunciador y advertidor para toda la humanidad»."),
"prophets_225": ("¿Qué aleya recitó el Profeta ﷺ al retirarse los ídolos de alrededor de la Kaaba?", ["«Ha venido la verdad y se ha desvanecido lo falso»", "«Te hemos dado una victoria clara»", "«Di: Él es Allah, Uno»", "«Cuando llegue el auxilio de Allah»"], "«Y di: ha venido la verdad y se ha desvanecido lo falso; ciertamente, lo falso está destinado a desvanecerse»."),
"prophets_226": ("¿Qué dicen los creyentes acerca de los mensajeros de Allah, al final de la sura Al-Baqara?", ["«No hacemos distinción entre ninguno de Sus mensajeros»", "«Seguimos solo al último»", "«Preferimos a uno»", "«Los ignoramos»"], "«No hacemos distinción entre ninguno de Sus mensajeros. Y dijeron: hemos oído y obedecido»."),
"prophets_227": ("¿Qué mensaje común llevó todo mensajero a su pueblo?", ["«Adorad a Allah y apartaos del tagut»", "«Construid templos»", "«Enriqueceos»", "«Escribid libros»"], "«Enviamos a cada comunidad un mensajero: adorad a Allah y apartaos del tagut»."),
"prophets_228": ("¿En qué lengua fue enviado cada mensajero, según la sura Ibrahim?", ["En la lengua de su pueblo, para explicarles", "Solo en árabe", "En hebreo", "En una lengua celestial"], "«No enviamos a ningún mensajero sino en la lengua de su pueblo, para explicarles»."),
"prophets_229": ("¿Qué se reveló a cada mensajero antes de Muhammad ﷺ, según la sura Al-Anbiya?", ["Que no hay más dios que Él: adoradle, pues", "Construir un santuario", "Conquistar tierras", "Guardar el secreto"], "«No enviamos antes de ti a ningún mensajero sin revelarle: no hay más dios que Yo, adoradme»."),
"prophets_230": ("En la sura Al-An'am, ¿qué grupo de profetas se enumera como la descendencia guiada de Ibrahim?", ["Dawud, Sulaiman, Ayyub, Yusuf, Musa y Harun, entre otros", "Solo Musa y 'Isa", "Solo Isma'il e Ishaq", "Solo Nuh y Hud"], "El pasaje enumera una larga estirpe de profetas a quienes Allah guio, y dice: «Así recompensamos a los que hacen el bien»."),
"prophets_231": ("¿Qué dice el Corán sobre los mensajeros unos respecto a otros?", ["Allah favoreció a unos sobre otros", "Todos tienen idéntico rango", "Solo cuenta el último", "Se ignoraban entre sí"], "«De esos mensajeros, hemos favorecido a unos sobre otros»."),
"prophets_232": ("¿Qué compromiso tomó Allah de los profetas, según la sura Al 'Imran?", ["Creer en el Mensajero que vendría confirmando lo que tenían, y apoyarlo", "No dejar nunca a su pueblo", "Construir cada uno un templo", "Escribir cada uno un libro"], "«Si viene a vosotros un Mensajero que confirma lo que tenéis, habréis de creer en él y auxiliarlo»."),
"prophets_233": ("¿Qué profetas nombra el Corán al decir que Allah les prescribió la misma religión?", ["Nuh, Ibrahim, Musa y 'Isa, junto con lo revelado al Profeta ﷺ", "Solo Adán e Idris", "Solo Dawud y Sulaiman", "Solo Hud y Salih"], "«Os ha prescrito en materia de religión lo que encomendó a Nuh, lo que te hemos revelado a ti, y lo que encomendamos a Ibrahim, a Musa y a 'Isa»."),
"prophets_234": ("¿Qué dice el Corán sobre los mensajeros cuya historia no relata?", ["Hay algunos cuya historia Allah no relató al Profeta ﷺ", "No existen", "Todos están nombrados", "No tienen importancia"], "«De ellos te hemos relatado la historia de algunos, y de otros no te la hemos relatado»."),
"prophets_235": ("¿De entre quiénes eligió Allah a todos Sus mensajeros, según la sura Yusuf?", ["De hombres de las ciudades, a quienes revelaba", "De los ángeles", "De los reyes", "Solo de los del desierto"], "«No enviamos antes de ti sino a hombres de las ciudades, a quienes revelábamos»."),
"prophets_236": ("¿Qué recuerda el Corán sobre los mensajeros desmentidos antes de Muhammad ﷺ?", ["Fueron pacientes hasta que les llegó Nuestro auxilio", "Se rindieron", "Se escondieron", "Cambiaron su mensaje"], "«Ya antes de ti fueron desmentidos mensajeros, pero tuvieron paciencia ante el desmentido hasta que les llegó Nuestro auxilio»."),
"prophets_237": ("¿Qué familias eligió Allah sobre los mundos, según la sura Al 'Imran?", ["Adán, Nuh, la familia de Ibrahim y la familia de 'Imran", "Los reyes de Egipto", "Las tribus de Medina", "La gente de Saba"], "«Allah eligió a Adán, a Nuh, a la familia de Ibrahim y a la familia de 'Imran sobre los mundos»."),
"prophets_238": ("¿Qué favores recordó Musa a su pueblo al invitarlos a entrar en la Tierra Santa?", ["Que Allah había puesto profetas entre ellos y los había hecho reyes", "Que les había dado naves", "Que les había dado oro", "Que les había dado caballos"], "«Pueblo mío, recordad el favor de Allah con vosotros: puso profetas entre vosotros y os hizo reyes»."),
"prophets_239": ("¿Cómo describían la Torá y el Evangelio al Profeta iletrado, según el Corán?", ["Ordena el bien, prohíbe el mal y les alivia sus cargas", "Trae riqueza", "Gobierna por la fuerza", "Construye templos"], "«…el profeta iletrado que hallan mencionado en la Torá y el Evangelio: les ordena el bien y les prohíbe el mal… y les libra de su carga»."),
"prophets_240": ("¿En quién dijo Nuh que se apoyaba al desafiar a su pueblo a conspirar?", ["En Allah, en quien depositaba su confianza", "En sus hijos", "En su tribu", "En su nave"], "«En Allah confío. Poneos de acuerdo, vosotros y vuestros socios»."),
"prophets_241": ("En la súplica de Ibrahim, ¿a quién atribuye la curación cuando enferma?", ["Solo a Allah", "A los médicos", "A las plantas", "Al tiempo"], "«Y cuando enfermo, es Él quien me cura», dijo Ibrahim describiendo a su Señor."),
"prophets_242": ("¿Con qué fue rescatado el hijo de Ibrahim, según la sura As-Saffat?", ["Con un sacrificio inmenso", "Con un rescate de oro", "Con una caravana", "Con un rebaño entero"], "«Y lo rescatamos con un sacrificio inmenso»."),
"prophets_243": ("¿En qué declaran creer los creyentes en la aleya «Decid: creemos en Allah…»?", ["En lo revelado a Ibrahim, Isma'il, Ishaq, Ya'qub, Musa, 'Isa y los profetas", "En un solo libro", "En un solo profeta", "En sus propias tradiciones"], "«Decid: creemos en Allah y en lo que se nos ha revelado, y en lo revelado a Ibrahim, Isma'il, Ishaq, Ya'qub…»"),
"prophets_244": ("¿Por qué relata Allah al Profeta ﷺ los relatos de los mensajeros?", ["Para afirmar su corazón", "Para entretenerlo", "Para enseñarle historia", "Para distraerlo"], "«Y todo lo que te relatamos de las noticias de los mensajeros es para afirmar con ello tu corazón»."),
"prophets_245": ("¿Qué se le ordenó decir al Profeta ﷺ sobre sí mismo, al final de la sura Al-Kahf?", ["«Yo no soy sino un hombre como vosotros; se me ha revelado que vuestro Dios es un Dios Único»", "«Soy un rey»", "«Soy un ángel»", "«Conozco lo oculto»"], "«Di: yo no soy sino un hombre como vosotros, a quien se le ha revelado que vuestro Dios es un Dios Único»."),
"prophets_246": ("¿Cómo describe la sura Al-Fath a quienes están con el Mensajero ﷺ?", ["Duros con los incrédulos, misericordiosos entre sí", "Ricos y numerosos", "Silenciosos y retirados", "Viajeros y comerciantes"], "«Muhammad es el Mensajero de Allah. Y quienes están con él son duros con los incrédulos, misericordiosos entre sí»."),
"prophets_247": ("¿Qué dice la sura An-Naym sobre las palabras del Profeta ﷺ?", ["No habla por capricho: no es sino una revelación inspirada", "Habla como poeta", "Habla como adivino", "Habla por su cuenta"], "«Vuestro compañero no se ha extraviado ni se ha desviado; no habla por capricho: no es sino una revelación inspirada»."),
"prophets_248": ("¿Qué se le ordenó al Profeta ﷺ cuando llegó el auxilio de Allah y la victoria?", ["Glorificar a su Señor con alabanza y pedirle perdón", "Celebrar con un banquete", "Levantar un monumento", "Descansar"], "«Cuando llegue el auxilio de Allah y la victoria… glorifica a tu Señor con alabanza y pídele perdón»."),
"prophets_249": ("¿Qué tres tareas atribuye la sura Al-Yumu'a al Mensajero enviado a los iletrados?", ["Recitarles las aleyas, purificarlos y enseñarles el Libro y la sabiduría", "Construir, comerciar y gobernar", "Escribir, contar y viajar", "Juzgar, castigar y recaudar"], "«Él es quien ha enviado entre los iletrados a un Mensajero de entre ellos, que les recita Sus aleyas, los purifica y les enseña el Libro y la sabiduría»."),
"prophets_250": ("¿Qué salvaguarda menciona el Corán mientras el Profeta ﷺ estaba entre ellos?", ["Allah no los castigaría mientras él estuviera entre ellos", "Serían ricos", "Vencerían siempre", "No morirían"], "«Pero Allah no los iba a castigar estando tú entre ellos»."),
}
